CREATE TABLE credit_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id), policy jsonb NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>0));
INSERT INTO credit_settings(id,policy) VALUES(true,'{"expiryEnabled":true,"carryForwardEnabled":true,"earlyCancellationRetainsCredit":true,"lateCancellationRetainsCredit":true,"absenceRetainsCredit":true,"illnessRetainsCredit":true}');
CREATE TABLE package_offers(id text PRIMARY KEY,name text NOT NULL,credits integer NOT NULL CHECK(credits>0),price_minor bigint NOT NULL CHECK(price_minor>0),currency text NOT NULL CHECK(currency='HKD'),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,policy_override jsonb);
CREATE TABLE purchases(id text PRIMARY KEY,student_id text NOT NULL REFERENCES students(id),created_by text NOT NULL REFERENCES users(id),idempotency_key text NOT NULL,request jsonb NOT NULL,terms jsonb NOT NULL,status text NOT NULL CHECK(status IN ('awaiting_expiry','pending_payment','paid')),expires_on date,expiry_assigned_by text REFERENCES users(id),expiry_assigned_at timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,UNIQUE(created_by,idempotency_key));
CREATE TABLE payment_attempts(id text PRIMARY KEY,purchase_id text NOT NULL REFERENCES purchases(id),created_by text NOT NULL REFERENCES users(id),idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN ('pending','failed','succeeded')),created_at timestamptz NOT NULL,UNIQUE(created_by,idempotency_key));
CREATE UNIQUE INDEX one_pending_attempt ON payment_attempts(purchase_id) WHERE status='pending';
CREATE TABLE credit_packages(id text PRIMARY KEY,purchase_id text NOT NULL UNIQUE REFERENCES purchases(id),student_id text NOT NULL REFERENCES students(id),credits integer NOT NULL CHECK(credits>0),expires_on date,policy jsonb NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE credit_movements(id text PRIMARY KEY,package_id text NOT NULL REFERENCES credit_packages(id),source text NOT NULL UNIQUE,available integer NOT NULL,reserved integer NOT NULL,consumed integer NOT NULL,expired integer NOT NULL,actor_id text NOT NULL REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE receipts(id text PRIMARY KEY,purchase_id text NOT NULL UNIQUE REFERENCES purchases(id),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL);
CREATE FUNCTION reject_finance_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'financial history is immutable'; END $$;
CREATE TRIGGER immutable_credit_movements BEFORE UPDATE OR DELETE ON credit_movements FOR EACH ROW EXECUTE FUNCTION reject_finance_history_mutation();
CREATE TRIGGER immutable_receipts BEFORE UPDATE OR DELETE ON receipts FOR EACH ROW EXECUTE FUNCTION reject_finance_history_mutation();
